"""Add current quotation projection and atomic synchronization.

Legacy records remain authoritative, including full quotation history.
Quantity represents remaining available capacity. Runtime projection access is read-only.
"""
from alembic import op

revision = '0005_proc_offers'
down_revision = '0004_proc_sync'
branch_labels = None
depends_on = None

SQL = "-- Current quotation projection. The complete history remains in authoritative records.\n-- quantity is remaining available offer capacity, not immutable original quoted quantity.\nCREATE TABLE public.proc_offers (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK (source_revision >= 1),\n    rfq_id varchar(64) NOT NULL,\n    supplier_id varchar(64) NOT NULL,\n    sku varchar(80) NOT NULL CHECK (length(sku) > 0),\n    quantity integer NOT NULL CHECK (quantity >= 0),\n    unit text NOT NULL CHECK (unit = 'piece'),\n    unit_price numeric(14,2) NOT NULL CHECK (unit_price > 0),\n    freight_per_piece numeric(14,2) NOT NULL CHECK (freight_per_piece >= 0),\n    fixed_freight numeric(14,2) NOT NULL CHECK (fixed_freight >= 0),\n    moq integer NOT NULL CHECK (moq >= 1),\n    pack_size integer NOT NULL CHECK (pack_size >= 1),\n    currency text NOT NULL CHECK (currency = 'AED'),\n    valid_until date NOT NULL,\n    delivery_date date NOT NULL,\n    specs jsonb NOT NULL CHECK (jsonb_typeof(specs) = 'object' AND specs <> '{}'::jsonb),\n    evidence_id varchar(64) NOT NULL,\n    recipient text NOT NULL,\n    terms text NOT NULL,\n    status text NOT NULL CHECK (length(status) > 0),\n    compliance jsonb NOT NULL CHECK (jsonb_typeof(compliance) = 'object'),\n    compliance_status text NOT NULL CHECK (length(compliance_status) > 0),\n    compliance_revision integer CHECK (compliance_revision >= 1),\n    technical_reviewer varchar(64),\n    assessment_reason text,\n    PRIMARY KEY (tenant,id),\n    FOREIGN KEY (tenant,rfq_id) REFERENCES public.proc_rfqs (tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY (tenant,supplier_id) REFERENCES public.proc_suppliers (tenant,id) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE INDEX ix_proc_offers_rfq_supplier ON public.proc_offers (tenant,rfq_id,supplier_id);\nCREATE INDEX ix_proc_offers_sku_valid ON public.proc_offers (tenant,sku,valid_until);\nALTER TABLE public.proc_offers ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.proc_offers FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_scope ON public.proc_offers TO supplypilot_app\n    USING (tenant = NULLIF(current_setting('supplypilot.tenant',true),''))\n    WITH CHECK (tenant = NULLIF(current_setting('supplypilot.tenant',true),''));\nCREATE POLICY migration_owner ON public.proc_offers TO supplypilot_migrator USING (true) WITH CHECK (true);\nREVOKE ALL ON TABLE public.proc_offers FROM PUBLIC, supplypilot_app;\nGRANT SELECT ON TABLE public.proc_offers TO supplypilot_app;\n\nCREATE FUNCTION public.sync_procurement_offer()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path = pg_catalog, pg_temp\nAS $$\nDECLARE d jsonb; money_field text; amount numeric;\nBEGIN\n    IF TG_OP = 'UPDATE' AND (OLD.kind='offer' OR NEW.kind='offer') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Quotation identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP = 'DELETE' THEN\n        IF OLD.kind='offer' THEN\n            DELETE FROM public.proc_offers WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind <> 'offer' THEN RETURN NEW; END IF;\n    d := NEW.data::jsonb;\n    -- Numeric columns must not silently round unsupported fractional currency units.\n    FOREACH money_field IN ARRAY ARRAY['unit_price','freight_per_piece','fixed_freight'] LOOP\n        amount := COALESCE(d->>money_field,CASE WHEN money_field='fixed_freight' THEN '0.00' END)::numeric;\n        IF amount IS DISTINCT FROM round(amount,2) OR amount::text IN ('NaN','Infinity','-Infinity') THEN\n            RAISE EXCEPTION 'Quotation money must be finite and have at most two decimal places' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    INSERT INTO public.proc_offers\n    VALUES (NEW.tenant,NEW.id,NEW.revision,d->>'rfq_id',d->>'supplier_id',d->>'sku',\n        (d->>'quantity')::integer,d->>'unit',(d->>'unit_price')::numeric,\n        (d->>'freight_per_piece')::numeric,COALESCE(d->>'fixed_freight','0.00')::numeric,\n        COALESCE(d->>'moq','1')::integer,COALESCE(d->>'pack_size','1')::integer,\n        d->>'currency',(d->>'valid_until')::date,(d->>'delivery_date')::date,\n        d->'specs',d->>'evidence_id',d->>'recipient',d->>'terms',d->>'status',\n        d->'compliance',d->'compliance'->>'status',(d->>'compliance_revision')::integer,\n        d->>'technical_reviewer',d->>'assessment_reason')\n    ON CONFLICT (tenant,id) DO UPDATE SET\n        source_revision=EXCLUDED.source_revision,rfq_id=EXCLUDED.rfq_id,supplier_id=EXCLUDED.supplier_id,\n        sku=EXCLUDED.sku,quantity=EXCLUDED.quantity,unit=EXCLUDED.unit,unit_price=EXCLUDED.unit_price,\n        freight_per_piece=EXCLUDED.freight_per_piece,fixed_freight=EXCLUDED.fixed_freight,\n        moq=EXCLUDED.moq,pack_size=EXCLUDED.pack_size,currency=EXCLUDED.currency,\n        valid_until=EXCLUDED.valid_until,delivery_date=EXCLUDED.delivery_date,specs=EXCLUDED.specs,\n        evidence_id=EXCLUDED.evidence_id,recipient=EXCLUDED.recipient,terms=EXCLUDED.terms,\n        status=EXCLUDED.status,compliance=EXCLUDED.compliance,compliance_status=EXCLUDED.compliance_status,\n        compliance_revision=EXCLUDED.compliance_revision,technical_reviewer=EXCLUDED.technical_reviewer,\n        assessment_reason=EXCLUDED.assessment_reason;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_offer() FROM PUBLIC, supplypilot_app;\nCREATE TRIGGER records_offer_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_offer();\nUPDATE public.records SET data=data WHERE kind='offer';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Use the verified backup rollback procedure; automatic quotation projection removal is disabled.')
